{
  "name": "@adaptiqai/opencode",
  "version": "0.1.5",
  "description": "AdaptiqAI for OpenCode and Kilo: your workspace's models, conversations AdaptiqAI remembers, and your saved knowledge, in one plugin.",
  "type": "module",
  "keywords": [
    "opencode-plugin",
    "kilo",
    "adaptiqai"
  ],
  "license": "UNLICENSED",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MrRopke/adaptiq-harness-plugins.git",
    "directory": "packages/opencode"
  },
  "files": [
    "lib/index.js",
    "README.md"
  ],
  "main": "./lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./server": "./lib/index.js"
  },
  "engines": {
    "opencode": ">=1.18.29"
  },
  "devDependencies": {
    "@types/node": "^22.15.0",
    "esbuild": "~0.25.12",
    "typescript": "~5.9.3",
    "vitest": "~3.2.7",
    "zod": "4.1.8",
    "@adaptiqai/core": "0.2.15"
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run"
  }
}
